 const concise=s.preferences.some(p=>p.active&&p.ownerId===a.actorId&&p.key==='response_length'&&/short|concise|brief/i.test(p.value));
 let answer=chosen.length?`Here is the relevant wording from ${chosen.map(x=>x.d.title).join(', ')}:\n\n${citations.map(x=>`“${x.quote}”`).join('\n\n')}\n\nCheck the defined terms, exceptions and any amendments before relying on an isolated passage.`:'Start with the intended purpose, the information or commitments involved, and who will receive or rely on them. Separate your current practice from the change you are considering.';
 if(confirmed.length)answer+=`\n\nConfirmed company context: ${confirmed.slice(0,concise?2:5).map(f=>`${f.predicate}: ${typeof f.value==='string'?f.value:JSON.stringify(f.value)} (${f.practice})`).join('; ')}.`;
 if(/summar|transcript|vendor|retention|recording|\bai\b/i.test(prompt))answer+='\n\nFor this change, establish whether you will use synthetic or customer data, the vendor’s role and retention, deployment status, and the commitments in each applicable customer agreement. A merged PR alone does not establish production deployment.';
 if(!available.length)answer+='\n\nYou can attach or paste one relevant agreement, or describe the real change. Broad integrations are optional.';
 answer+='\n\nThis is a bounded local response from the available records. Jurisdiction-specific legal coverage is unverified; novel interpretation stays with a qualified reviewer.';
 return {text:answer,citations,factIds:confirmed.slice(0,concise?2:5).map(f=>f.id),sourceIds:[...new Set([...citations.map(x=>x.sourceId),...confirmed.flatMap(f=>f.provenance.sourceIds)])]};
