  const intent:Message['intent']=/^\s*(looks good|go ahead|yes|approved|send it|publish it)[.!\s]*$/i.test(prompt)?'ambiguous':/\b(what if|hypothetical|thinking of|considering|explore|maybe|suppose)\b/i.test(prompt)?'scenario':/\b(remember|actually|correction|our .* is|we retain|we use)\b/i.test(prompt)?'correction':/\b(short answer|be concise|keep .* brief|shorter responses)\b/i.test(prompt)?'preference':'question';
  const user:Message={...base(s,a,conversation.scope),conversationId:conversation.id,role:'user',channel:c.channel||'web',text:prompt,intent,artifactIds:[],citations:[],generation:'human',retention:'workspace_policy',voiceConfirmed:!voice||c.voiceConfirmed===true};s.messages.push(user);
