  const assistant:Message={...base(s,a,conversation.scope,response.sourceIds,'Bounded local response from authorized evidence'),conversationId:conversation.id,role:'assistant',channel:c.channel||'web',text:response.text,intent,artifactIds:artifacts,citations:response.citations,generation:'bounded_local',retention:'workspace_policy',voiceConfirmed:true};assistant.provenance.factIds=response.factIds||[];s.messages.push(assistant);user.artifactIds=artifacts;touch(conversation);activity(s,a,c.type,'Conversation continued','Response and linked records saved.',conversation,conversation.matterId);return {conversationId:conversation.id,messageId:assistant.id,artifactIds:artifacts};
